def canon(m):
    cands=[]
    cur=m
    for _ in range(4):
        for f in (lambda a:[r for r in a], lambda a:[r[::-1] for r in a]):
            s=f(cur)
            if all(len(r)==len(cur[0]) and len(s)==len(cur) for r in s):
                try: tuple(map(tuple,s))
